-- ==========================================================================
-- A Guantes Negros — datos semilla para Supabase
-- ==========================================================================
-- Generado desde src/data/catalog.ts. Correlo DESPUÉS de schema.sql.
-- Es idempotente: si el slug ya existe, actualiza la fila (upsert), así que
-- podés volver a correrlo para resincronizar el catálogo.
-- ==========================================================================

begin;

-- ---- Categorías ---------------------------------------------------------
on conflict (slug) do update set
  name = excluded.name, tagline = excluded.tagline,
  mascot = excluded.mascot, art = excluded.art;

-- ---- Productos ----------------------------------------------------------
on conflict (slug) do update set
  name = excluded.name, brand = excluded.brand, price = excluded.price,
  compare_at = excluded.compare_at, category = excluded.category, art = excluded.art,
  rating = excluded.rating, reviews = excluded.reviews, badge = excluded.badge,
  featured = excluded.featured, description = excluded.description,
  specs = excluded.specs, stock = excluded.stock;

commit;
